"""Low-level DPAPI crypto primitives, implemented from the documented algorithms.

Nothing here is copied from GPL sources (dpapick / dpapilab). The derivations are
written from Microsoft's documented key schedule and validated against real Windows
master keys and blobs.

Two facts are easy to get wrong and are called out here:

* The master-key KDF is Microsoft's iterated-HMAC derivation, which folds every round
  into the running accumulator (``T ^= HMAC(pwd, T)``). It is NOT RFC 2898 PBKDF2;
  standard PBKDF2 does not open real Windows master keys.
* ``CryptDeriveKey`` only runs the ipad/opad expansion when the hash output is shorter
  than the key it has to produce; otherwise it returns the hash output truncated.
"""
import hashlib
import hmac
import struct

from Crypto.Cipher import AES, DES3

# Microsoft CALG_* algorithm identifiers that appear in master-key files and blobs.
CALG_SHA1 = 0x8004
CALG_HMAC = 0x8009
CALG_SHA_256 = 0x800C
CALG_SHA_512 = 0x800E
CALG_DES3 = 0x6603
CALG_AES_128 = 0x660E
CALG_AES_192 = 0x660F
CALG_AES_256 = 0x6610

_HNAME = {CALG_SHA1: 'sha1', CALG_SHA_256: 'sha256', CALG_SHA_512: 'sha512'}
_HLEN = {CALG_SHA1: 20, CALG_SHA_256: 32, CALG_SHA_512: 64}
_BLOCK = {CALG_SHA1: 64, CALG_SHA_256: 64, CALG_SHA_512: 128}
# cipher -> (key length, iv/block length)
_CIPHER = {CALG_AES_128: (16, 16), CALG_AES_192: (24, 16), CALG_AES_256: (32, 16),
           CALG_DES3: (24, 8)}


def hash_name(alg_hash):
    """The hashlib name for a CALG_* hash identifier."""
    return _HNAME[alg_hash]


def hash_len(alg_hash):
    return _HLEN[alg_hash]


def cipher_sizes(alg_crypt):
    """(key length, iv length) for a CALG_* cipher identifier."""
    return _CIPHER[alg_crypt]


def _xor(a, b):
    return bytes(x ^ y for x, y in zip(a, b))


def dpapi_kdf(password, salt, dklen, iterations, alg_hash):
    """Microsoft's iterated-HMAC derivation (the master-key KDF).

    Each round folds into the accumulator ``t ^= HMAC(pwd, t)``. This is the
    derivation Windows uses for master keys, not RFC 2898 PBKDF2.
    """
    hname = _HNAME[alg_hash]
    out = b''
    block = 1
    while len(out) < dklen:
        t = hmac.new(password, salt + struct.pack('!L', block), hname).digest()
        u = t
        for _ in range(iterations - 1):
            u = hmac.new(password, t, hname).digest()
            t = _xor(t, u)
        out += t
        block += 1
    return out[:dklen]


def crypt_derive_key(digest, alg_hash, need):
    """CryptDeriveKey: the hash output when long enough, else the ipad/opad expansion."""
    hname, block = _HNAME[alg_hash], _BLOCK[alg_hash]
    if len(digest) > block:
        digest = hashlib.new(hname, digest).digest()
    if len(digest) >= need:
        return digest[:need]
    padded = digest.ljust(block, b'\x00')
    ipad = bytes(b ^ 0x36 for b in padded)
    opad = bytes(b ^ 0x5c for b in padded)
    return (hashlib.new(hname, ipad).digest() + hashlib.new(hname, opad).digest())[:need]


def cbc_decrypt(alg_crypt, key, iv, data):
    if alg_crypt == CALG_DES3:
        return DES3.new(key, DES3.MODE_CBC, iv).decrypt(data)
    return AES.new(key, AES.MODE_CBC, iv).decrypt(data)


def session_key_legacy(masterkey, nonce, alg_hash, entropy=None, extra=None):
    """Pre-Win7 session key: ipad/opad over the master key, then the nonce.

    ``extra`` (the signed blob region, used only for the verification key) folds into
    the outer hash, matching the layout validated against real blobs.
    """
    hname, block = _HNAME[alg_hash], _BLOCK[alg_hash]
    mk = hashlib.sha1(masterkey).digest() if len(masterkey) > 20 else masterkey
    mk = mk.ljust(block, b'\x00')
    ipad = bytes(mk[i] ^ 0x36 for i in range(block))
    opad = bytes(mk[i] ^ 0x5c for i in range(block))
    inner = hashlib.new(hname, ipad)
    inner.update(nonce)
    if entropy is not None:
        inner.update(entropy)
    outer = hashlib.new(hname, opad)
    outer.update(inner.digest())
    if extra is not None:
        outer.update(extra)
    return outer.digest()


def session_key_win7(masterkey, nonce, alg_hash, entropy=None, extra=None):
    """Win7+ session key: HMAC(masterkey, nonce [+ entropy] [+ signed region])."""
    mk = hashlib.sha1(masterkey).digest() if len(masterkey) > 20 else masterkey
    digest = hmac.new(mk, nonce, _HNAME[alg_hash])
    if entropy is not None:
        digest.update(entropy)
    if extra is not None:
        digest.update(extra)
    return digest.digest()


SESSION_KEY_ALGOS = (session_key_win7, session_key_legacy)
